// ============================================================
// Validate Webhook & Apply Debounce
// ============================================================
// 1. Check webhook secret token for geofence trigger
// 2. Wait 5 minutes for Google Drive sync to complete
// 3. Merge triggers from both webhook sources
// ============================================================

const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || item.json;

// Validate secret token (skip for manual trigger)
const expectedSecret = $env.GEOFENCE_WEBHOOK_SECRET || '';
const providedSecret = headers['x-webhook-secret'] || body.secret || '';

if (expectedSecret && providedSecret !== expectedSecret) {
  throw new Error('Invalid webhook secret. Rejecting request.');
}

// Debounce: this is handled by the Wait node that follows
return [{ json: { triggerType: body.trigger || 'geofence', timestamp: new Date().toISOString() } }];

// ============================================================
// Routing Logic: Group Chat vs DM
// ============================================================
// Rules:
//   - 2+ friends detected → Send to GROUP chat
//   - 1 friend detected → Send as DM to that friend
//   - 0 friends → Skip (handled by previous node)
//
// For photos: sent as DOCUMENT (preserves full quality)
// For videos: sent as normal MEDIA (WhatsApp compresses anyway)
//
// Output: adds routing instructions to each item
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  const friends = item.json.friends_identified || [];
  const friendCount = friends.length;
  const isVideo = item.json.is_video;

  if (friendCount >= 2) {
    // GROUP CHAT: photo has 2+ friends
    results.push({
      json: {
        ...item.json,
        _routing: {
          type: 'group',
          recipientJid: $env.WHATSAPP_GROUP_JID,
          recipientName: 'Squad Group',
          sendAs: isVideo ? 'media' : 'document',
          friends: friends,
          caption: isVideo ? '' : `📸 ${friends.join(' & ')}`,
        }
      }
    });
  } else if (friendCount === 1) {
    // DM: photo has exactly 1 friend
    results.push({
      json: {
        ...item.json,
        _routing: {
          type: 'dm',
          friendName: friends[0],
          sendAs: isVideo ? 'media' : 'document',
          friends: friends,
          caption: '',
        }
      }
    });
  }
}

return results;

// ============================================================
// Contact Lookup
// ============================================================
// For DMs, we need to look up the friend's WhatsApp JID.
// This queries the friends_contacts table.
//
// Alternative: Use Google Sheets lookup node if you prefer
// managing contacts in a spreadsheet.
// ============================================================

const item = $input.first();
const routing = item.json._routing;

if (routing.type === 'group') {
  // Group messages don't need contact lookup
  return [{ json: item.json }];
}

// For DMs, the recipient JID will be set after DB lookup
return [{
  json: {
    ...item.json,
    _contactLookupNeeded: true,
    _friendToLookup: routing.friendName ? routing.friendName.replace(/'/g, "''") : null,
  }
}];

// ============================================================
// Merge Contact Info & Build Send Payload
// ============================================================
// Combines routing decision with contact lookup results.
// Builds the final payload for Evolution API.
// ============================================================

const item = $input.first();
const routing = item.json._routing;

let recipientJid, recipientName;

if (routing.type === 'group') {
  recipientJid = routing.recipientJid;
  recipientName = routing.recipientName;
} else {
  // DM — use looked-up contact
  const contact = item.json;
  recipientJid = contact.whatsapp_jid;
  recipientName = contact.display_name || routing.friendName;

  if (!recipientJid) {
    throw new Error(`No WhatsApp JID found for friend: ${routing.friendName}. Add them to friends_contacts table.`);
  }

  // Check send preference
  if (contact.send_preference === 'group_only') {
    // This friend only wants group messages, skip DM
    return [{ json: { ...item.json, _skip: true, _skipReason: 'Friend prefers group_only' } }];
  }
}

return [{
  json: {
    mediaId: item.json.media_id || item.json.mediaId,
    sessionId: item.json.session_id || item.json.sessionId,
    localPath: item.json.local_path || item.json.localPath,
    originalFilename: item.json.original_filename || item.json.originalFilename,
    isVideo: item.json.is_video || item.json.isVideo,
    recipientJid: recipientJid,
    recipientName: recipientName,
    recipientType: routing.type,
    sendAs: routing.sendAs,
    caption: routing.caption || '',
    friends: routing.friends,
  }
}];

// ============================================================
// Human-like Delay (Ban Prevention)
// ============================================================
// WhatsApp monitors for bot-like behavior. We add random delays
// between messages to appear more natural.
//
// Strategy:
//   - Random delay between MIN and MAX ms per message
//   - After every BATCH_SIZE messages, take a longer cooldown
// ============================================================

const minDelay = parseInt($env.WA_MIN_DELAY_MS) || 3000;
const maxDelay = parseInt($env.WA_MAX_DELAY_MS) || 8000;

// Random delay in this range
const delay = Math.floor(Math.random() * (maxDelay - minDelay)) + minDelay;

// Sleep
await new Promise(resolve => setTimeout(resolve, delay));

return $input.all();

// ============================================================
// Generate Delivery Summary
// ============================================================
// After all media is sent, compile a summary message
// to send to yourself via WhatsApp.
// ============================================================

const items = $input.all();
const summary = {
  totalSent: items.length,
  groupMessages: items.filter(i => i.json.recipientType === 'group').length,
  dmMessages: items.filter(i => i.json.recipientType === 'dm').length,
  friends: [...new Set(items.flatMap(i => i.json.friends || []))],
  timestamp: new Date().toISOString(),
};

const summaryText = `📸 *AutoSharePics Summary*\n\n` +
  `✅ Sent: ${summary.totalSent} file(s)\n` +
  `👥 Group: ${summary.groupMessages}\n` +
  `💬 DMs: ${summary.dmMessages}\n` +
  `👤 Friends: ${summary.friends.join(', ')}\n` +
  `🕐 ${new Date().toLocaleString('en-IN')}`;

return [{ json: { summaryText, ...summary } }];
